PARAM_DEFS = {0: ('imu_enable', 'BNO086 IMU present (SPI). 0 = skip init/poll and stop gating STARTUP/CALIBRATION/RUNNING on it; also blocks RUNNING since real pitch feedback is required. Persisted; takes effect at boot (needs reboot).'), 3: ('buzzer_volume', 'Buzzer master volume. 0.0 = silent, 1.0 = max, scales linearly in between. Persisted; takes effect at boot.'), 4: ('led_enable', 'Status RGB LED present. 0 = skip init/poll. Persisted; takes effect at boot.'), 5: ('hip_l_enable', 'Left AK45 hip motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 6: ('hip_r_enable', 'Right AK45 hip motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 7: ('wheel_l_enable', 'Left ODrive wheel motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 8: ('wheel_r_enable', 'Right ODrive wheel motor present. 0 = skip CAN traffic and stop gating STARTUP/CALIBRATION on it. RUNNING/JUMPING blocked unless all 4 motor-enable flags are set. Persisted; takes effect at boot.'), 9: ('watchdog_enable', 'Enable hardware watchdog (WDOG1) — auto-reboots the MCU if the main loop stalls. Default off. Takes effect at boot; once armed cannot be disabled in software until the next reset.'), 10: ('loop_profile_enable', 'Debug: log a rolling max of loop()-section timings once/sec. Not persisted.'), 513: ('hip_running_kp', 'MIT position gain used for hip setpoints while RUNNING.'), 514: ('hip_running_kd', 'MIT damping gain used for hip setpoints while RUNNING.'), 515: ('hip_running_tff_ret', "MIT feedforward torque used for hip setpoints while RUNNING, fully retracted leg (alpha=0). Interpolated toward hip_running_tff_ext by the same gain-schedule alpha as the LQR gains. The hip hold is proportional-only (no integrator), so its steady-state sag is (holding torque - tff)/kp: a single constant tff can only null that at one leg height, and the 4-bar's mechanical advantage makes the required holding torque vary with height. Measure the sag at several alpha holds and set the two anchors from that. Units are true N·m at the hip output (AK45-10 MIT torque full scale ±8). Values tuned before the torque-scale fix were 18/8 too large; the v2->v3 param-store migration rescales them once."), 516: ('hip_running_ramp_s', 'Seconds to ramp kp/tff from 0 to their running value after entering RUNNING, easing in instead of snapping. kd applies at full value throughout. 0 = no ramp.'), 517: ('hip_cmd_rate_lim', 'Maximum RUNNING hip-height command slew [normalized extension per second]. The CH3 target is rate-limited before conversion to hip positions; 0 disables limiting. Default 0.2 gives a five-second full-stroke transition and reduces hip reaction impulses and linkage chatter.'), 518: ('hip_running_tff_ext', 'MIT feedforward torque used for hip setpoints while RUNNING, fully extended leg (alpha=1). Companion to hip_running_tff_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 512: ('estop_hip_disable', '1 = exit MIT mode on ESTOP entry and re-enter on reset; 0 = leave MIT running through ESTOP.'), 288: ('calib_seek_speed', 'Slow position-ramp speed toward the retract limit switch [rad/s].'), 289: ('calib_move_speed', 'Slow position-ramp speed while releasing and backing away from the switch [rad/s].'), 290: ('calib_seek_kp', 'Weak MIT position-gain target while seeking toward the retract switch; authority slews up from zero over calib_rampdown_s.'), 291: ('calib_kd', 'MIT damping gain used for all switch-homing motion.'), 292: ('calib_seek_trq_lim', 'Motor-torque safety threshold while seeking toward the retract switch [N·m]; it must be exceeded continuously for calib_trq_trip_ms before calibration fails. The AK45 MIT reply field is shaft torque, not amps.'), 293: ('calib_move_trq_lim', 'Motor-torque safety threshold while moving away from an initially pressed retract switch or backing off after zeroing [N·m]; it must be exceeded continuously for calib_trq_trip_ms before calibration fails. The AK45 MIT reply field is shaft torque, not amps.'), 294: ('calib_backoff_rad', 'Actual encoder distance the hip must move away from the switch during initial clearance and after homing [rad]; default 5 degrees. This calibrated retracted endpoint is also the fixed STANDING_UP hip target. Set this value before calibration; changing it afterward requires recalibration so the stored hip limits are rebuilt.'), 295: ('calib_range_l_rad', 'Left hip extended software limit as an angular delta from retract-switch zero [rad]. 1.48353 = 85 deg = the v4 stop-to-stop travel (Q_RET +28 deg to Q_EXT -57 deg), which assumes the retract switch trips AT the +28 deg stop; if it trips early, reduce by that offset or t=1 drives into the extended stop.'), 296: ('calib_range_r_rad', 'Right hip extended software limit as an angular delta from retract-switch zero [rad]. 1.48353 = 85 deg = the v4 stop-to-stop travel (Q_RET +28 deg to Q_EXT -57 deg), which assumes the retract switch trips AT the +28 deg stop; if it trips early, reduce by that offset or t=1 drives into the extended stop.'), 297: ('calib_seek_timeout', 'Maximum time to seek a retract switch before calibration faults [s].'), 298: ('calib_release_to', 'Maximum time allowed for an initially or newly pressed switch to release [s].'), 299: ('calib_max_seek_rad', 'Maximum commanded travel while seeking a retract switch before calibration faults [rad].'), 300: ('calib_max_rel_rad', 'Maximum commanded travel allowed while moving away from a retract switch; must be at least calib_backoff_rad [rad].'), 301: ('calib_trq_trip_ms', 'How long a hip must stay above its calibration torque limit before calibration faults [ms]. 0 trips immediately.'), 302: ('calib_move_kp', 'MIT position-gain target while moving away from the retract switch against robot weight; uses the same calib_rampdown_s authority slew.'), 303: ('calib_rampdown_s', 'Seconds for calibration Kp to slew up from zero and for Kp/Kd to ramp back to zero at successful completion or operator cancellation; 0 disables ramping.'), 305: ('calib_bypass_en', '1 = allow RUNNING without completed switch calibration or valid hip limits; dangerous bench-test bypass.'), 768: ('wm_enc_timeout_ms', "Wheel encoder feedback watchdog timeout [ms]; increase if CAN is flaky. ODrive PID gains aren't exposed here — tune via the ODrive USB GUI (CAN can't reach those properties on 0.5.x)."), 769: ('wm_vel_slew_max', 'Plausibility limit on encoder-velocity change [turns/s^2]. An encoder sample that moved further than this since the last accepted one is treated as corruption and the previous value is held instead; 0 disables the check. Default 1500 sits just above the ~1300 turns/s^2 a free-spinning wheel can reach at MOTOR_TRQ_MAX, so only physically impossible jumps are rejected. Fails open after 3 consecutive rejections so a real runaway is never masked. Defence-in-depth against CAN/encoder noise — not a substitute for fixing the wiring.'), 1024: ('lqr_enable', '1 = wheel torque output active; 0 = LQR runs but outputs zero.'), 1025: ('sim_pitch_rad', 'Pitch value injected in place of real IMU pitch when enable_sim_pitch=1.'), 1026: ('lqr_torque_limit', "|tau_sym| clamp [N·m]; hard max 7.0. READONLY — slewed automatically from the active CH9 speed profile's torque_lim. Edit profile1/2/3_torque_lim instead."), 1027: ('wm_vel_limit', 'Per-tick soft wheel velocity governor [turns/s]; ESTOP at 2x this.'), 1028: ('vel_pi_en', '1 = velocity PI active; 0 = theta_ref fixed at 0.'), 1029: ('vel_pi_kp', 'Velocity PI proportional gain [rad/(m/s)].'), 1030: ('vel_pi_ki', 'Velocity PI integral gain [rad/m].'), 1031: ('vel_pi_kff', 'Velocity PI acceleration feedforward gain [s²·rad/m] (≈ 1/g).'), 1033: ('vel_pi_rate_lim', 'theta_ref slew rate limit [rad/s].'), 1034: ('vel_pi_int_max', 'Velocity PI integrator anti-windup clamp [rad·s].'), 1035: ('v_cmd_ms', 'Desired forward velocity setpoint [m/s]; GUI/Phase3 testing.'), 1036: ('yaw_pi_en', '1 = yaw PI active; 0 = tau_yaw fixed at 0.'), 1037: ('yaw_pi_kp', 'Yaw PI proportional gain [N·m/(rad/s)].'), 1038: ('yaw_pi_ki', 'Yaw PI integral gain [N·m/rad].'), 1039: ('yaw_pi_torque_max', '|tau_yaw| clamp [N·m].'), 1040: ('yaw_pi_int_max', 'Yaw PI integrator anti-windup [N·m·s].'), 1041: ('omega_cmd_rds', 'Desired yaw rate [rad/s]; positive = CCW from above.'), 1042: ('ff1_alpha', 'Hip reaction cancel feedforward gain [0–1]; start at 0, ramp up.'), 1043: ('ff2_alpha', 'Gravity compensation feedforward gain [0–1]; start at 0, ramp up.'), 1044: ('ff1_kt_hip', 'Scale from reported hip torque to hip output torque. The AK45 MIT reply field is already shaft torque in N·m, so this is 1.0 and remains only as an FF1 trim. READONLY, edit + reflash to change.'), 1045: ('jump_enable', 'Master gate. 0 = SET_MODE(JUMPING) and the CH6 trigger are both refused and the state is never entered. 1 = armed. Independent of jump_effort, which must ALSO be non-zero for any push to happen.'), 1046: ('jump_torque_max', 'EXTEND hip torque CEILING [N·m]. Commanded torque is jump_torque_max * jump_effort, and during EXTEND kp=0, so that product is the ONLY thing holding the leg up. Increase -> harder push available. Decrease -> weaker push, but NOT a gentler jump: below roughly 3.5 N·m the leg cannot support the robot and collapses onto the retract stop instead of extending. Default 7.0 is the AK45-10 peak; set it once and sweep jump_effort instead. Above 8 cannot be encoded by the MIT protocol.'), 1049: ('jump_ramp_down', 'Torque taper WIDTH approaching jump_extend_angle [rad; GUI shows deg]. Torque scales linearly from full at (jump_extend_angle - this) down to zero exactly at jump_extend_angle, so the push eases off instead of stopping dead. Increase -> torque eases off earlier and over a longer distance: softer arrival, less shock into the linkage, slightly lower jump. Decrease -> full torque held closer to the target then cut abruptly: higher jump, harsher stop.'), 1050: ('jump_omega_max', "Hip speed at which EXTEND torque has faded to ZERO [rad/s; GUI shows deg/s]. Torque is multiplied by (1 - |hip speed| / this), so the faster the leg swings the less torque it gets - a stand-in for the motor's real torque-speed droop, and the cleanest single knob for capping jump height. Peak vertical speed is roughly this * 0.19 m per rad. Increase -> torque sustained to higher leg speeds, faster extension, higher jump. Decrease -> torque cuts out sooner, lower jump; down near 2-3 rad/s the leg barely moves at all."), 1051: ('jump_hs_margin', 'Hard cutoff distance from the CALIBRATED EXTENDED LIMIT [rad; GUI shows deg]. Torque is zeroed outright - and EXTEND ends - whenever either hip comes within this of that limit. A mechanical backstop independent of jump_extend_angle, so a mis-set extend target cannot drive the linkage into its stop, which sits essentially on the 4-bar singularity. Increase -> bigger safety buffer, push stops further out, less usable stroke. Decrease -> more stroke available, less protection against overshoot at speed.'), 1052: ('jump_kp', "Hip position gain for CROUCH and RETRACT. NOT used in EXTEND, where kp is forced to 0, or after live landing detection, where the normal RUNNING hip controller takes over. Increase -> tighter tracking of the crouch and tuck ramps, but a bigger stiffness step away from hip_running_kp on entry. Decrease -> softer tracking with more sag under the leg's static load (sag = holding torque / kp)."), 1053: ('jump_kd', 'Hip damping for CROUCH and RETRACT. Increase -> better damped, less overshoot and ringing at the ends of the ramps, but more resistance to fast motion. Decrease -> livelier response, may ring against jump_kp. LANDING and HANDOFF use the normal RUNNING hip controller.'), 1054: ('jump_ext_kd', 'Hip damping during EXTEND only, where kp=0 makes this the sole feedback term. Increase -> more resistance to the leg accelerating: gentler, lower jump, less slam into the extend end. Decrease -> freer acceleration, higher jump, harsher arrival. Keep it small - it subtracts directly from the push.'), 1055: ('jump_ext_timeout', 'Maximum time in EXTEND before RETRACT is forced [s]. A phase CAP, not a target: EXTEND normally ends on reaching jump_extend_angle or the hard cutoff. Increase -> the push may run longer, so more of the stroke is used and the jump is higher, provided torque has not already tapered away. Decrease -> the push is truncated early, lower jump. Also feeds the overrun budget, so raising it moves the FAULT_JUMP_TIMEOUT deadline with it.'), 1329: ('jump_effort', 'Fraction of jump_torque_max actually commanded during EXTEND - the one dial to sweep during bring-up. Increase -> harder push. Decrease -> weaker push, and once the product drops below roughly 3.5 N·m the leg collapses rather than extending, so this is NOT a safety dial once the robot is on the ground. NOT a vertical speed: this remains an open-loop push effort. Persistent; defaults to 1.0. jump_enable remains the independent boot-safe master gate and defaults to 0.'), 1330: ('jump_crouch_angle', 'CROUCH target, as hip extension angle from the retract switch [rad; GUI shows deg]. 0 = at the switch, fully retracted. Decrease -> deeper crouch: more stroke to push through and a higher jump, but closer to the retract hard stop and a bigger drop to get there. Increase -> shallower crouch, gentler entry, less stroke and a lower jump. Replaces the old jump_crouch_time, whose distance was not a parameter at all, so the crouch speed silently depended on the ride height you launched from.'), 1331: ('jump_crouch_speed', "PEAK hip speed during CROUCH [rad/s; GUI shows deg/s]. Duration is derived as 1.875 * travel / this, the 1.875 being the minimum-jerk profile's peak-to-mean rate ratio. Increase -> quicker crouch; a fast drop preloads the jump but is a much larger disturbance to the balance loop. Decrease -> slower and gentler, easier to watch and to balance through, but the whole sequence lengthens and the overrun budget grows with it."), 1332: ('jump_extend_angle', 'EXTEND target, as hip extension angle from the retract switch [rad; GUI shows deg]. Torque tapers to zero over the last jump_ramp_down before it, and the phase ends on reaching it. Increase -> longer push, more stroke used, higher jump, finishing closer to the extended limit. Decrease -> shorter push, lower jump. jump_hs_margin is a separate lower-level cutoff, so setting this too high is still caught by the mechanism rather than by the operator.'), 1333: ('jump_retract_speed', 'PEAK hip speed during RETRACT, the tuck back to the landing pose [rad/s; GUI shows deg/s]. Duration derived as 1.875 * travel / this. Increase -> faster tuck, legs up sooner in flight, landing pose reached earlier. Decrease -> slower tuck; slower than the flight time and the robot lands mid-ramp instead of in the settled pose. Replaces a hardcoded 0.20 s whose speed depended on how far EXTEND happened to travel.'), 1357: ('jump_retract_torque', 'Commanded hip-feedback torque ceiling during RETRACT [N*m]. Firmware predicts kp*(q_cmd-q)+kd*(dq_cmd-dq) independently for each hip and scales kp/kd together when it exceeds this value. This preserves the damping ratio and avoids the approximately 8 N*m demand produced by an abrupt EXTEND-to-RETRACT velocity reversal. It is not a motor current limit: external impact or back-driving can still make measured shaft torque exceed it. Default 7 N*m; the matched jump retained its 2.5 cm clearance target at 7, while 6 delayed the tuck enough to reduce clearance below 2 cm.'), 1335: ('jump_retract_angle', 'RETRACT target - the pose the robot tucks to and lands on while live contact detection remains armed [rad; GUI shows deg]. NEGATIVE means "return to the pre-jump pose", the default and the behaviour before this parameter existed. Increase -> lands more extended, leaving leg travel to absorb the impact but a higher CG to catch. Decrease -> lands more retracted and more stable, with less suspension travel left. Landing re-seeds the hip rate limiter from the measured pose, so CH3 slews back in rather than stepping after handoff.'), 1334: ('jump_torque_rate', 'EXTEND torque onset RATE [N·m/s]. Time to reach the commanded torque is jump_torque_max * jump_effort / this. Increase -> sharper onset, more of the phase spent at full push, higher jump, bigger shock into the linkage. Decrease -> softer onset, gentler on the mechanism, less of the phase at full torque. Replaces jump_ramp_up, a fixed softstart duration, which had it backwards: at fixed time a bigger push ramped in proportionally faster.'), 1336: ('jump_nudge_fwd_vel', "Forward velocity added to the pilot's live v_cmd_ms during the final jump_nudge_fwd_dur seconds of CROUCH [m/s]. The pilot command is not replaced: effective command = stick command + this offset. 0 disables the nudge. Default 0.15 m/s."), 1337: ('jump_nudge_fwd_dur', 'Duration of the forward velocity nudge immediately before CROUCH hands off to EXTEND [s]. If longer than the computed crouch trajectory, the nudge covers the whole crouch. 0 disables it. Default 0.10 s.'), 1338: ('jump_air_accel_z', 'Retired compatibility parameter; ignored by firmware. Landing detection is gyro-only and the production IMU configuration disables linear acceleration. The ID remains reserved so stored parameter sets and protocol clients do not shift.'), 1339: ('jump_land_accel_z', 'Retired compatibility parameter; ignored by firmware. Landing detection is gyro-only and the production IMU configuration disables linear acceleration. The ID remains reserved so stored parameter sets and protocol clients do not shift.'), 1340: ('jump_land_gyro_imp', 'Landing threshold: sum of 3-axis gyro-vector changes over the fixed 12 ms impact window [rad/s]. Only fresh IMU reports count and at least two changes are required, rejecting held control-tick values and a lone bad sample. 2.5 detected both reference landings at 0.560/0.570 s after the jump command.'), 1341: ('jump_land_min_air', 'Touchdown detector blanking time measured from RETRACT entry [s]. It prevents EXTEND/takeoff and early retraction gyro impulses from declaring landing. Default 0.16 s leaves 50 ms before the earliest reference landing (0.21-0.22 s after RETRACT).'), 1342: ('jump_land_timeout', 'Maximum time from RETRACT entry to a live touchdown detection [s]. RETRACT continues toward/holds its landing pose while waiting. Expiry raises FAULT_JUMP_TIMEOUT instead of blindly handing an unconfirmed flight to RUNNING.'), 1343: ('jmp_handoff_kp_mul', 'Multiplier on the normal alpha-scheduled LQR pitch gain during jump HANDOFF. 1 = RUNNING gain; greater than 1 gives a harder post-impact pitch catch without retuning steady running. Default 1.5.'), 1344: ('jmp_handoff_kr_mul', 'Multiplier on the normal alpha-scheduled LQR pitch-rate gain during jump HANDOFF. Increase for more impact damping; too high can make the catch noisy or torque-limited. Default 1.5.'), 1345: ('jmp_handoff_kv_mul', 'Multiplier on lqr_k_vel during jump HANDOFF. Default 1 keeps the normal velocity term while pitch/rate recovery gains are raised. Reduce if wheel-speed error fights attitude recovery immediately after impact.'), 1346: ('jmp_handoff_torque', 'HANDOFF-scoped replacement for lqr_torque_limit [N*m], applied to tau_sym and the mixed per-wheel output. 0 inherits the RUNNING/profile value; MOTOR_TRQ_MAX remains the hard ceiling. Default 0.6 N*m.'), 1347: ('jmp_handoff_vel_lim', 'HANDOFF-scoped wheel soft-governor threshold [turns/s], also used as the runaway watchdog baseline while handoff is active. 0 inherits wm_vel_limit. The reference jumps exceeded the 6 turns/s RUNNING governor for 0.13-0.17 s, so default 10 preserves braking authority through the catch.'), 1348: ('jmp_handoff_pitch', 'Absolute trim-relative LQR pitch error required for HANDOFF capture [rad], together with jmp_handoff_rate and both wheels inside the normal RUNNING governor. Default 0.05 rad.'), 1349: ('jmp_handoff_rate', 'Absolute pitch-rate threshold for jump HANDOFF capture [rad/s].'), 1350: ('jmp_handoff_hold_s', 'Continuous time inside the jump HANDOFF pitch/rate/normal-wheel-speed capture band before returning to RUNNING [s].'), 1351: ('jmp_handoff_timeout', 'Maximum time allowed for post-landing HANDOFF to enter and hold its capture band [s]. Expiry raises FAULT_JUMP_TIMEOUT rather than enabling the steady RUNNING limits on an unrecovered robot.'), 1352: ('jmp_arm_fwd_ms', 'Jump-request-time gate: refuse stateMachine_request_jump() if measured forward wheel_vel_avg_ms exceeds this [m/s]. Checked once at arm, not enforced during the jump. Deliberately looser than jmp_arm_bwd_ms — some forward speed helps the launch, same idea as jump_nudge_fwd_vel.'), 1353: ('jmp_arm_bwd_ms', 'Jump-request-time gate: refuse stateMachine_request_jump() if measured backward speed (-wheel_vel_avg_ms) exceeds this [m/s, magnitude]. Checked once at arm, not enforced during the jump. Tighter than jmp_arm_fwd_ms since backward speed does not help a jump and more often means the robot is already being pushed around.'), 1354: ('jmp_arm_yaw_rate', 'Jump-request-time gate: refuse stateMachine_request_jump() if |imu_yaw_rate()| exceeds this [rad/s]. Checked once at arm, not enforced during the jump. Rejects arming while the robot is actively turning/spinning.'), 1355: ('jmp_arm_roll', 'Jump-request-time gate: refuse stateMachine_request_jump() if |imu_roll()| exceeds this [rad, magnitude]. Checked once at arm, not enforced during the jump. Deliberately tighter than roll_watchdog_limit (a mid-flight trip threshold, off by default) — this just keeps a jump from launching while already leaning hard sideways.'), 1356: ('jmp_air_vel_lim', "CROUCH/EXTEND/RETRACT-scoped wheel soft-governor threshold [turns/s]; the runaway watchdog trips at 2x this while airborne, same relationship jmp_handoff_vel_lim has to LANDING/HANDOFF. 0 inherits wm_vel_limit. Wheels are unloaded and legitimately spin fast in the air, unlike jmp_handoff_vel_lim's post-landing on-ground case, so this wants real headroom: added 2026-08-13 after a genuine airborne RETRACT (accel_z dipped to -28 m/s2) tripped FAULT_WHEEL_RUNAWAY at wm_r=-12.97 turns/s against the plain 12.0 (2x wm_vel_limit=6.0) ceiling that used to apply through the whole pre-landing sequence."), 1056: ('enable_sim_pitch', '1 = use sim_pitch_rad instead of real IMU pitch.'), 1057: ('sim_pitch_rate', 'Pitch rate injected in place of real IMU pitch rate when enable_sim_prate=1 [rad/s].'), 1058: ('enable_sim_prate', '1 = use sim_pitch_rate instead of real IMU pitch rate.'), 1059: ('pitch_watchdog_en', "1 = ESTOP (FAULT_PITCH_WATCHDOG) if pitch exceeds pitch_watchdog_fwd_ret/ext or pitch_watchdog_bwd_ret/ext (gain-scheduled by leg height) for > 200 ms. Default on and NOT persisted — always starts back on after reboot so a bench-test disable can't silently survive into a real run."), 1060: ('lqr_k_pitch_ret', 'LQR pitch gain, fully retracted leg. Default -0.3 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1061: ('lqr_k_rate_ret', 'LQR pitch-rate gain, fully retracted leg. Default -0.1 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1062: ('lqr_k_pitch_ext', 'LQR pitch gain, fully extended leg. Default -0.3 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1063: ('lqr_k_rate_ext', 'LQR pitch-rate gain, fully extended leg. Default -0.1 — conservative bench-tuning starting point, not the earlier sim-derived value.'), 1064: ('lqr_k_vel', 'LQR velocity-error gain, invariant across leg height. Default -0.007.'), 1065: ('run_wheel_bypass_en', '1 = allow RUNNING mode to arm with wheel_l/r_enable off (bench-test only, e.g. a software-triggered smoke test with hips also disabled, no real torque anywhere). Independent of calib_bypass_en, which only covers the hip check. Persistent since 2026-08-09 so a bench session survives a power cycle -- it used to boot to 0 every time, which silently blocked arming after every reboot with a message naming the motor rather than the missing bypass. setup() logs a loud WARN on any boot that comes up with it set, which is what replaces the boot-to-safe guarantee.'), 1066: ('alpha_force_ret_en', '1 = force the hip gain-schedule blend to alpha=0.0 (fully-retracted LQR gains), bypassing the hm_limits valid-calibration check entirely. For hardware tuning at the retracted anchor without needing a completed calibration. PERSISTENT (changed 2026-08-09, at operator request, for multi-session tuning at a single leg height): it now survives a power cycle, so a forgotten override can leave the robot flying retracted gains at full extension. Firmware logs a WARN at boot whenever it comes up set -- that warning is the only thing standing in for the old always-boots-to-0 guarantee, so do not ignore it. Note it also pins gain_sched_alpha to 0 in telemetry, not just in the blend.'), 1067: ('gui_motion_ctrl_en', '1 = v_cmd_ms/omega_cmd_rds are driven by GUI/CLI param_set instead of CH2/CH4; radio arming (CH10) is unaffected. Auto-clears (reverting to radio control) if no GUI command arrives for 300 ms. Not persisted — always boots to 0.'), 1068: ('standup_enable', "Master gate: 0 = arm goes STANDBY->RUNNING directly (today's behavior). 1 = arm routes through STANDING_UP recovery first. Default 0."), 1070: ('standup_pitch_min', 'Arm-time-only lower signed pitch bound [rad] considered recoverable when STANDING_UP is requested (negative = backward). Default -0.6 (~-34°). Does not bound the catch itself once underway — see standup_div_bwd for that. Parameter ID 0x042E is retained from the former positive-magnitude standup_pitch_bwd; param-store v4 negates its persisted value once during migration.'), 1069: ('standup_pitch_max', 'Arm-time-only upper signed pitch bound [rad] considered recoverable when STANDING_UP is requested (positive = forward). Default 0.6 (~34°). Does not bound the catch itself once underway — see standup_div_fwd for that. Parameter ID 0x042D is retained from the former standup_pitch_fwd.'), 1073: ('standup_crouch_time', "CROUCH phase duration [s]: the commanded minimum-jerk excursion from the hips' pose at arm to the calibrated retracted endpoint. The phase does not end until the ramp has run its full length AND both hips have stopped moving, so this is the excursion time, not a timeout. Default 0.30."), 1327: ('standup_crouch_kpf', 'Hip stiffness during the CROUCH excursion, as a fraction of hip_running_kp/hip_running_tff_ret (kd always runs at its full value). Faded in from 0 on the same minimum-jerk profile as the position ramp, so arming applies no torque step even when the legs start outside the calibrated span. Lower = gentler excursion but more sag against gravity; the sag is pulled out by the STIFFEN ramp that follows. Default 0.5.'), 1328: ('standup_stiff_time', 'STIFFEN phase duration [s]: hips hold the calibrated retracted endpoint while kp and the hip feedforward ramp linearly from standup_crouch_kpf to their full hip_running_* values. The LQR is engaged only after this ramp completes AND the hips settle inside the strict position/velocity band at full stiffness. Default 1.0.'), 1074: ('standup_k_pitch', 'Recovery P gain on pitch [N*m/rad]. NOT READ in the current design: STANDING_UP reuses controlLoop_run() (the RUNNING LQR, velocity PI, wheel governor and runaway watchdog) instead of a standup-specific law, so the equivalent RUNNING params govern. Retained for a future standup-specific control law.'), 1075: ('standup_k_rate', 'Recovery D gain on pitch rate. NOT READ in the current design: STANDING_UP reuses controlLoop_run() (the RUNNING LQR, velocity PI, wheel governor and runaway watchdog) instead of a standup-specific law, so the equivalent RUNNING params govern. Retained for a future standup-specific control law.'), 1076: ('standup_torque_lim', 'STANDING_UP-scoped replacement for lqr_torque_limit [N*m]: while the state is active this clamps tau_sym and the mixed per-wheel output instead of the RUNNING value, so the catch can be given the authority to swing the body up without detuning the balance loop. 0 = use lqr_torque_limit (off by default). MOTOR_TRQ_MAX (7 N*m) remains the hard ceiling either way.'), 1077: ('standup_vel_limit', "STANDING_UP-scoped replacement for wm_vel_limit [turns/s]: while the state is active this is both the per-wheel soft governor threshold and the baseline for the runaway watchdog's 2x trip. The governor zeroes wheel torque outright once the wheel passes it in the driven direction, so the RUNNING value is what ends the catch's backward acceleration early; raise this to let the wheels run out far enough to tilt the body forward. 0 = use wm_vel_limit (off by default)."), 1078: ('standup_cap_pitch', '|pitch - lqr_pitch_trim_ret| below this [rad] (+ rate below standup_cap_rate) for standup_cap_hold => captured (handoff to RUNNING). Kept well inside pitch_wd_bwd_ret minus |lqr_pitch_trim_ret|: at the old 0.12 a capture at the backward edge of the band handed off ~0.002 rad from the backward pitch-watchdog trip angle, so a successful catch was immediately followed by FAULT_PITCH_WATCHDOG in RUNNING.'), 1079: ('standup_cap_rate', '|pitch_rate| capture threshold [rad/s].'), 1080: ('standup_cap_hold', 'Continuous in-band duration [s] required before handoff.'), 1081: ('standup_timeout', 'Max time [s] in one RECOVER attempt before declaring it failed-to-converge (not diverged).'), 1082: ('standup_max_retries', 'Retry attempts after the first (total attempts = this + 1); integer stored as a float.'), 1083: ('standup_retry_pause', 'Wheels-off settle time [s] between retry attempts.'), 1084: ('lqr_pitch_trim_ret', "Balance-point pitch offset [rad], fully retracted leg (alpha=0). This is the retracted endpoint of trim(alpha) = trim_ret + alpha*(trim_ext-trim_ret) + trim_curve*alpha*(1-alpha). The lean the LQR holds for zero velocity compensates a CG that is not exactly over the wheel axle. Default -0.14 rad (~-8 deg), measured on the bench 2026-07-25: with this at 0 the vel-PI integrator was doing the trim's job, permanently eating ~8 deg of the backward lean budget. Not currently a live-tune target (see LIVE_TUNE_SLOTS in main.cpp) — edit via the Params tab, or repoint a live-tune slot at this param for a future bench session."), 1085: ('lqr_pitch_trim_ext', 'Balance-point pitch offset [rad], fully extended leg (alpha=1). This is the extended endpoint of the quadratic height schedule; lqr_trim_curve changes only the interior of the alpha range.'), 1086: ('theta_max_fwd_ret', 'Velocity-PI commanded-lean clamp, forward direction, fully retracted leg [rad, magnitude]. theta_ref is clamped to +this value when leaning forward (pitch positive = lean forward). Gain-scheduled toward vel_pi_theta_max_fwd_ext by the same alpha as the LQR gains. Split from vel_pi_theta_max because the leg linkage clears the ground at a different forward angle than backward.'), 1087: ('theta_max_bwd_ret', 'Velocity-PI commanded-lean clamp, backward direction, fully retracted leg [rad, magnitude]. theta_ref is clamped to -this value when leaning backward. Gain-scheduled toward vel_pi_theta_max_bwd_ext by the same alpha as the LQR gains. Split from vel_pi_theta_max because the leg linkage clears the ground at a different backward angle than forward.'), 1088: ('theta_max_fwd_ext', 'Velocity-PI commanded-lean clamp, forward direction, fully extended leg [rad, magnitude]. Companion to vel_pi_theta_max_fwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1089: ('theta_max_bwd_ext', 'Velocity-PI commanded-lean clamp, backward direction, fully extended leg [rad, magnitude]. Companion to vel_pi_theta_max_bwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1090: ('pitch_wd_fwd_ret', 'Pitch watchdog forward trip threshold, fully retracted leg [rad, magnitude]. ESTOPs (FAULT_PITCH_WATCHDOG) if pitch > this value for > 200 ms (pitch positive = lean forward). Gain-scheduled toward pitch_watchdog_fwd_ext by the same alpha as the LQR gains. Split from the old symmetric PITCH_WATCHDOG_RAD constant because the leg linkage collides with the ground at a different forward angle than backward. Requires pitch_watchdog_en=1.'), 1091: ('pitch_wd_bwd_ret', 'Pitch watchdog backward trip threshold, fully retracted leg [rad, magnitude]. ESTOPs (FAULT_PITCH_WATCHDOG) if pitch < -this value for > 200 ms. Gain-scheduled toward pitch_watchdog_bwd_ext by the same alpha as the LQR gains. Split from the old symmetric PITCH_WATCHDOG_RAD constant because the leg linkage collides with the ground at a different backward angle than forward. Requires pitch_watchdog_en=1.'), 1092: ('pitch_wd_fwd_ext', 'Pitch watchdog forward trip threshold, fully extended leg [rad, magnitude]. Companion to pitch_watchdog_fwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1093: ('pitch_wd_bwd_ext', 'Pitch watchdog backward trip threshold, fully extended leg [rad, magnitude]. Companion to pitch_watchdog_bwd_ret; the two are linearly interpolated by the gain-schedule alpha. Defaults to the same value as the retracted anchor until bench-tuned separately.'), 1094: ('standup_div_fwd', 'In-progress divergence limit: max forward pitch [rad] tolerated *during* a RECOVER attempt before declaring it diverged (FAULT_STANDUP_FAILED, no retry). Deliberately looser than standup_pitch_max (the arm-time-only gate) so a saturated catch has overshoot budget instead of self-tripping the instant it starts. Must stay checked with the same debounce as a normal fault (not instantaneous) to avoid a single noisy IMU sample aborting a good catch.'), 1095: ('standup_div_bwd', 'In-progress divergence limit: max backward pitch [rad] tolerated *during* a RECOVER attempt before declaring it diverged (FAULT_STANDUP_FAILED, no retry). This is the only pitch bound in effect while STANDING_UP suppresses the pitch watchdog, and the leg linkage reaches the ground on a backward lean well before the forward limit, so it is tighter than standup_div_fwd rather than symmetric with it.'), 1325: ('standup_ret_gains', '1 = pin the gain-schedule alpha to 0 (the retracted anchor) for the duration of STANDING_UP, so the LQR gains, pitch trim, barrier threshold and watchdog thresholds use their _ret values while the hips are held at the calibrated retracted endpoint. Scoped to STANDING_UP only, unlike alpha_force_ret_en which pins alpha globally. Set to 0 to schedule on measured leg height instead.'), 1096: ('lqr_barrier_k', 'Backward soft-limit barrier gain [N·m/rad]. Adds extra backward-recovery torque, on top of the normal LQR term, once pitch swings past -lqr_barrier_th (gain-scheduled ret/ext). Zero and exactly inert in normal operation (only engages past the threshold); starts at 0 — tune up on the bench once lqr_barrier_th is set below pitch_wd_bwd.'), 1097: ('lqr_barrier_th_ret', "Backward pitch magnitude [rad] past which the lqr_barrier_k soft limit engages, fully retracted leg. Default ~12°, between vel_pi's theta_max_bwd_ret (~10°, the normal saturated lean) and pitch_wd_bwd_ret (~15°, the hard ESTOP) so the barrier bites before the watchdog does. Gain-scheduled toward lqr_barrier_th_ext by the same alpha as the LQR gains."), 1098: ('lqr_barrier_th_ext', 'Backward pitch magnitude [rad] past which the lqr_barrier_k soft limit engages, fully extended leg. Companion to lqr_barrier_th_ret; defaults to the same value until bench-tuned separately.'), 1099: ('plant_id_en', 'Arm the control-loop plant-identification chirp. Non-persistent and inert at 0. The firmware auto-clears it after plant_id_dur and whenever RUNNING/JUMPING exits.'), 1100: ('plant_id_amp', 'Plant-identification chirp amplitude [N*m], added to tau_sym before the normal lqr_torque_limit clamp. Non-persistent.'), 1101: ('plant_id_f0', 'Plant-identification linear chirp start frequency [Hz]. Non-persistent.'), 1102: ('plant_id_f1', 'Plant-identification linear chirp end frequency [Hz]. Non-persistent.'), 1103: ('plant_id_dur', 'Plant-identification chirp duration [s]. The excitation auto-disarms when this time elapses. Non-persistent.'), 1104: ('lqr_trim_curve', 'Interior curvature [rad] for the balance-point pitch-trim height schedule: trim(alpha) = trim_ret + alpha*(trim_ext-trim_ret) + lqr_trim_curve*alpha*(1-alpha). It is zero at alpha=0 and alpha=1, contributes one quarter of its value at alpha=0.5, and default 0 preserves the previous linear interpolation. Negative values add more backward (negative) trim at intermediate leg heights.'), 1280: ('radio_hip_cmd', 'Hip extension command from CH3 [0=retracted, 1=extended]; firmware-written, stale when the radio link is dead.'), 1281: ('radio_vel_max', "Max forward speed mapped from full CH2 deflection [m/s]. READONLY — copied from the active CH9 profile's vel_max. Edit profile1/2/3_vel_max instead."), 1282: ('radio_yaw_max', "Max yaw rate mapped from full CH4 deflection [rad/s]. READONLY — copied from the active CH9 profile's yaw_max. Edit profile1/2/3_yaw_max instead."), 1283: ('live_tune_ch7_val', 'Live-tune shadow value for CH7\'s knob, mapped into whatever param CH7 is currently wired to for the CH5/CH6-selected group in main.cpp\'s LIVE_TUNE_SLOTS table (see live_tune.h) — group 0 lqr_k_pitch_ret [-0.1,-2.0] (widened 2026-07-26; the 2026-07-25 bench run pegged the old -0.5 end stop), group 1 vel_pi_kp [0.05,1.0], group 2 roll_kp [0.3,4.0]. min/max here is the union across all three groups\' ranges, display-only — the firmware write uses param_force_set and is never clamped by this param\'s own bounds. Only takes effect (overrides the real param in the control loop) once the knob has been swept through the active group\'s target\'s current value ("pickup", avoids a step change) and live-tune mode is active (RUNNING + calibration switch up). Write live_tune_latch=1 to persist the shadow into the real param. Firmware-written, stale when the radio link is dead.'), 1307: ('live_tune_ch8_val', "Live-tune shadow value for CH8's knob — same mechanism as live_tune_ch7_val, min/max is likewise the display-only union across groups (group 0 lqr_k_rate_ret [-0.01,-1.0], widened 2026-07-26 alongside CH7 so the rate/pitch ratio stays reachable as k_pitch grows; group 1 vel_pi_ki [0.02,0.5]; group 2 roll_kd [0.02,0.5]). See LIVE_TUNE_SLOTS in main.cpp."), 1296: ('profile1_vel_max', 'Speed profile 1 (slow) max forward speed [m/s]; CH9 3-position switch selects the active profile.'), 1297: ('profile1_yaw_max', 'Speed profile 1 (slow) max yaw rate [rad/s].'), 1298: ('profile1_torque_lim', 'Speed profile 1 (slow) LQR torque limit [N·m].'), 1299: ('profile2_vel_max', 'Speed profile 2 (normal) max forward speed [m/s].'), 1300: ('profile2_yaw_max', 'Speed profile 2 (normal) max yaw rate [rad/s].'), 1301: ('profile2_torque_lim', 'Speed profile 2 (normal) LQR torque limit [N·m].'), 1302: ('profile3_vel_max', 'Speed profile 3 (fast) max forward speed [m/s].'), 1303: ('profile3_yaw_max', 'Speed profile 3 (fast) max yaw rate [rad/s].'), 1304: ('profile3_torque_lim', 'Speed profile 3 (fast) LQR torque limit [N·m].'), 1305: ('active_profile', 'Active speed profile index (0/1/2), selected by CH9; firmware-written, READONLY.'), 1306: ('live_tune_latch', "Write 1 while live-tuning (RUNNING + calibration switch up) to persist every currently-picked-up LIVE_TUNE_SLOTS entry's shadow value into its real param. One-shot: firmware performs the latch(es) and resets this to 0. Slots that haven't picked up yet (knob never swept through the target's current value) are skipped, not latched at their un-picked-up shadow value. Ignored outside live-tune mode."), 1284: ('live_tune_multi_en', 'Selects what the CH5/CH6 switches do. 0 (default) = SIMPLE: CH5 is the SD-log switch (flip up to start recording, down to stop) and CH6 is the jump trigger (one jump per rising edge, RUNNING only, still gated by jump_enable); live tuning is entirely inactive because no switch is free to select a gain group. 1 = LEGACY: the original three-group scheme where CH5+CH6 combinations pick group 0/1/2 (CH5 down+CH6 up, CH5 up+CH6 down, both down; both up = inactive) while RUNNING, and neither switch touches SD logging or jumping -- a tuning session trades both away for the knobs, so it is bench-only. All three gain groups (lqr_k_pitch_ret/lqr_k_rate_ret, vel_pi, roll) are reachable only in LEGACY mode -- nothing was removed, it is behind this flag. A log must still be STARTED in STANDBY/ESTOP (opening one preallocates and blocks ~96 ms), but recording then continues through RUNNING.'), 1308: ('roll_ctrl_en', '1 = enable the roll controller: a PD loop on roll angle/rate that adds a differential hip position offset (extend one leg, retract the other) to level/lean the body. Active in RUNNING and the post-contact jump LANDING/HANDOFF recovery, but not during jump launch/flight. Default off — with it off the hips are held symmetrically exactly as before.'), 1309: ('roll_kp', 'Roll PD proportional gain: hip position offset [rad] per rad of roll error (roll_cmd_rad - measured roll).'), 1310: ('roll_kd', 'Roll PD derivative gain: hip position offset [rad] per rad/s of measured roll rate (damping term).'), 1322: ('roll_ki', 'Roll PI integral gain: hip position offset [rad] per rad-second of accumulated roll error. Nulls the steady-state roll droop a P-only law leaves against a standing CG/leg-length asymmetry (measured -1.9 deg mean, 98% one-sided, on the 2026-07-28 run). Default 0 = disabled, identical to the previous PD behaviour. Note the integrator output is a persistent differential leg offset, which shifts the CG laterally toward the low wheel -- keep roll_int_max tight and watch roll_watchdog_limit. Conditional-integration anti-windup: the integral only freezes when it would push an already-saturated offset further past roll_offset_max, and always stays free to unwind.'), 1323: ('roll_int_max', 'Roll PI integrator state clamp [rad-s]. Bounds how much standing asymmetry the integral can absorb, and therefore how far it can walk the legs apart on its own: the resulting offset contribution is roll_ki * this, still clamped by roll_offset_max. Keep it small -- a wound-up roll integrator parks the CG laterally off-centre, eating margin against the lateral tip-over the roll watchdog guards.'), 1311: ('roll_offset_max', 'Clamp on the differential hip position offset [rad] produced by the roll PD loop, applied +offset to one hip and -offset to the other. Bounds how far a bad gain can drive the legs apart; also clamped to calibrated hip travel.'), 1312: ('roll_rate_lim', "Slew-rate limit [rad/s] on the roll setpoint (roll_cmd_rad) before it enters the PD loop, so a snapped stick doesn't step-perturb the pitch balancer."), 1313: ('roll_watchdog_en', "1 = ESTOP (FAULT_ROLL_WATCHDOG) if |roll| > roll_watchdog_limit for > 200 ms (lateral tip guard). Default off, persistent across reboot and reflash (changed 2026-07-26 — was default-on and non-persistent specifically so a bench-test disable couldn't silently survive into a real run; that safety property no longer holds now that this is persisted default-off)."), 1314: ('roll_watchdog_limit', '|roll| threshold [rad] that trips FAULT_ROLL_WATCHDOG after 200 ms (default ~20°). Set well inside the lateral tip-over angle.'), 1326: ('wheel_runaway_en', '1 = ESTOP (FAULT_WHEEL_RUNAWAY) if either wheel exceeds 2x wm_vel_limit for > 50 ms. Set 0 only for bench work that legitimately spins the wheels past the governor (free-spin torque tests, encoder-scaling checks) — it removes the hard backup behind the per-tick velocity governor, so a real runaway then relies on the pitch watchdog alone. Persistent, so a disable survives a power cycle; setup() logs a loud WARN whenever it boots with the check off.'), 1315: ('hip_roll_kp', 'Hip MIT position gain [N·m/rad] used for the hip hold while the roll controller is active, replacing hip_running_kp. Set soft so the legs are backdrivable by obstacles (active suspension); keep hip_running_tff high enough that the legs still hold height under load.'), 1316: ('hip_roll_kd', 'Hip MIT damping gain [N·m·s/rad] used for the hip hold while the roll controller is active, replacing hip_running_kd.'), 1317: ('roll_cmd_rad', 'Roll setpoint [rad] from CH1, = CH1_norm * radio_roll_max; firmware-written, zeroed when the radio link is dead. READONLY.'), 1318: ('radio_roll_max', "Max roll setpoint mapped from full CH1 deflection [rad]. READONLY — copied from the active CH9 profile's roll_max. Edit profile1/2/3_roll_max instead."), 1319: ('profile1_roll_max', 'Speed profile 1 (slow) max roll setpoint [rad]; CH9 selects the active profile. Conservative — well inside the lateral tip angle. The 0.785 rad (45 deg) ceiling on this and its siblings is a bench-testing headroom figure, not a safe operating value: nothing downstream knows where the CG is, so anything approaching it relies entirely on roll_watchdog_en and roll_offset_max to stop a tip-over.'), 1320: ('profile2_roll_max', 'Speed profile 2 (normal) max roll setpoint [rad].'), 1321: ('profile3_roll_max', 'Speed profile 3 (fast/aggressive) max roll setpoint [rad] (~10°).'), 1358: ('lean_turn_en', "1 = master enable for coordinated-turn lean. Requires roll_ctrl_en=1 (the lean is delivered by the roll controller's differential hip offset) and lean_gain>0. The radio's lean button gates it too, so the feature needs both a persistent opt-in and a physical press."), 1359: ('lean_gain', 'Scale on the coordinated-turn lean, roll_cmd = -lean_gain*atan(v*omega/g). NOT 1.0 physically: the track is fixed, so differential hip extension shifts the CoM rather than rotating the vehicle about its contact line, and the shift per radian of body tilt depends on CoM height above the hip pivot. Default 0 (inert); walk it up a ladder like jump_effort after the suspended sign check.'), 1360: ('lean_max_rad', 'Hard clamp on the coordinated-turn lean [rad]. Must stay well inside roll_watchdog_limit (0.35 default) or the feature trips the very watchdog it exists to keep you away from. 0.15 rad = 8.6 deg.'), 1361: ('lean_min_ms', 'Forward-speed deadband [m/s] below which no lean is commanded. Spinning in place has no centripetal term to cancel, and an explicit floor stops standstill jitter from dithering the roll setpoint.'), 1362: ('lean_cmd_rad', 'Read-only mirror of the lean component currently being added to roll_cmd_rad [rad]. Lets the GUI and the radio HUD show what the turn compensation is actually asking for, separately from the stick.'), 1363: ('lean_authority', "Read-only fraction of the requested lean the leg geometry can deliver at the current ride height, min(t,1-t)*2. Zero at full crouch and full extension, where the roll controller's headroom clamp silently removes all differential travel. Exists so the operator can be told why the robot is not leaning.")}
